import { create_update_calender } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    editBlockDate: Boolean,
    ViewInfo: Object
  },
  data() {
    return {
      loading: false,
      selectedOption: "",
      priceAmount: this.ViewInfo?.price || "",
      Enable_selectedDate: this.ViewInfo.items.is_blocked || true
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.selectedOption = "";
    },
    confirmEnable() {
      this.Enable_selectedDate = false;
      this.Unblock_Selected_date(true); // Call with flag true
    },
    async Unblock_Selected_date(isFromConfirm = false) {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(create_update_calender, {
          input: {
            guest_house_id: this.ViewInfo.items.guest_house_id,
            calender_date: this.ViewInfo.items.calender_date,
            day_price: isFromConfirm ? this.ViewInfo.items.day_price : this.priceAmount,
            is_blocked: isFromConfirm ? this.Enable_selectedDate : this.ViewInfo.items.is_blocked
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.create_update_calender);
        // console.log("GraphQL Response:", response);

        if (response.Status === "SUCCESS") {
          // console.log("Date updated successfully");
          this.$emit("successMsg", response.Message);
          this.loading = false;
          this.selectedOption = "";
        } else {
          // console.error("Failed to update date");
          this.$emit("errorMsg", response.Message);
          this.loading = false;
        }
      } catch (error) {
        this.loading = false;
        console.error("Error updating date:", error);
      }
    }
  }
};
